-- PT content for Article 3
INSERT INTO
  endurancetrio_hub.article_content (id, article_id, locale, title, subtitle, intro_text, full_text, meta_title, meta_description, version, created_at, updated_at)
VALUES
  (
    5,
    3,
    'pt',
    'Triatlo de São Martinho do Porto: Muito mais do que uma prova',
    NULL,
    '<p>A história do Triatlo de São Martinho do Porto começou, de certa forma, com um telefonema.</p>',
    '<p>No final de 2021, eu tinha acabado de desafiar cerca de uma dezena de amigos alcobacenses para fazermos juntos o IRONMAN 70.3 Cascais do ano seguinte. Depois de vários anos a competir por um clube da zona de Sintra, queria criar em Alcobaça um grupo de pessoas ligadas ao triatlo. Falei com a Direção do Clube de Natação de Alcobaça e foi assim que nasceu a Secção de Triatlo do CNAL.</p><p>Um dia, um desses amigos telefonou-me a perguntar se eu sabia por que razão estava uma viatura da Federação de Triatlo de Portugal estacionada em frente à Câmara Municipal de Alcobaça. Não fazia ideia.</p><p>Telefonei ao João Raimundo, que conhecia pessoalmente Sérgio Dias, então Presidente da Federação. Poucos minutos depois soubemos que Hugo Nalha, Vice-Presidente da Federação tinha estado reunido com João Santos, Vereador do Desporto, para avaliar a possibilidade de realizar uma prova de triatlo em São Martinho do Porto. A resposta tinha sido negativa, porque se entendia que um evento daquela natureza só faria sentido se existisse um clube de triatlo no concelho.</p><p>A ironia era evidente.</p><p><strong>Havia tudo o que era necessário, exceto o conhecimento de que havia tudo.</strong></p><p>Conhecia profissionalmente Hermínio Rodrigues, Presidente da Câmara Municipal de Alcobaça, e pedi-lhe uma reunião para lhe apresentar a recém-criada Secção de Triatlo do CNAL. A partir daí, tudo aconteceu rapidamente.</p><p>Quando se juntaram à mesma mesa a Câmara Municipal, a Federação de Triatlo de Portugal, a Junta de Freguesia de São Martinho do Porto e o CNAL, foi muito fácil perceber que havia uma enorme convergência de vontades.</p><p>E duas frases ditas numa das primeiras reuniões acabaram por definir aquilo que o evento viria a ser.</p><p>Hermínio Rodrigues lançou-nos o desafio:</p><blockquote><strong>“Façam um evento que orgulhe os alcobacenses.”</strong></blockquote><p>Sérgio Dias acrescentou:</p><blockquote><strong>“O CNAL que trate da festa, que a FTP trata da competição.”</strong></blockquote><p>Penso que o ADN do Triatlo de São Martinho do Porto nasceu ali.</p><p>Definimos cinco objetivos. Promover São Martinho do Porto. Promover o desporto e o triatlo no concelho e na região. Homenagear os triatletas olímpicos de Alcobaça. Criar uma prova de grande qualidade que marcasse positivamente atletas e público. E trazer para uma prova de distância sprint alguma da qualidade e do glamour que encontramos nas grandes provas internacionais de longa distância.</p><p>Hoje, olhando para as quatro edições, são sobretudo estes dois últimos objetivos que melhor representam aquilo que fizemos.</p><p>Eu tinha participado no IRONMAN Barcelona e no IRONMAN Cascais. Nestas provas, um atleta pode pagar perto de mil euros por uma inscrição e participam milhares de pessoas. Essa dimensão financeira permite oferecer experiências extraordinárias.</p><p>No Triatlo de São Martinho do Porto, uma inscrição rondava os 20 euros.</p><p><strong>O nosso desafio era olhar para o que de melhor se faz no mundo, mas manter os pés bem assentes na realidade.</strong></p><p>Isso obrigava-nos a ser criativos.</p><p>Talvez nenhum exemplo represente melhor essa forma de pensar do que o parque de transição no areal.</p><p>Na <a href="/pt/events/2022/300001/overview">primeira edição</a>, em 2022, utilizámos a Rua Eng. Francisco Cavaleiro. Tivemos 714 inscritos e percebemos imediatamente que aquele espaço não permitiria acompanhar o crescimento que os indicadores já faziam prever.</p><p>No dia 4 de dezembro de 2022, pelas 18 horas, eu, o Sérgio Dias, o Nuno Vieira, Presidente da Junta de Freguesia de São Martinho do Porto, e o João Raimundo estávamos no areal. Tínhamos escolhido aquela hora porque a maré era igual à que encontraríamos no dia e hora da <a href="/pt/events/2023/300002/overview">prova de 2023</a> e precisávamos de analisar vários aspetos técnicos.</p><p>O problema do parque de transição voltou à conversa.</p><p>Entre brincadeiras e algum desespero surgiram soluções como “deitamos um prédio abaixo”, “chegamos o prédio para o lado” ou “alcatroamos a praia”.</p><p>Até que a brincadeira deixou de parecer completamente absurda.</p><p>Eu disse: alcatroar a praia não, evidentemente, mas talvez pudéssemos encontrar um material suficientemente rígido para permitir aos atletas correr sobre o areal.</p><p>Começámos a explorar a ideia. Encontrámos uma empresa local que produz placas de madeira para a construção civil e que tinha material com defeitos estéticos que podia ser adquirido a um preço compatível com os nossos recursos.</p><p>Nasceu assim o parque de transição no areal.</p><p>Aquilo que começou quase como uma piada transformou-se numa das imagens mais marcantes do evento e alterou completamente a organização da prova, reduziu o impacto no trânsito da vila e criou uma zona de competição extraordinária para atletas e público. E talvez o melhor parque de transição do mundo!</p><p>Logo na primeira edição percebemos que o Triatlo de São Martinho do Porto não seria uma prova igual às outras. Praticamente tudo o que procurávamos fazer tinha como ponto de partida uma pergunta muito simples:</p><p><strong>Como podemos tornar isto melhor para quem participa e para quem assiste?</strong></p><p>Foi assim com as bancadas. Com as refeições oferecidas aos atletas e acompanhantes. Com o merchandising. Com os ecrãs gigantes. Com o sistema de som. Com as cerimónias de abertura. Com a comunicação. Com os prémios de finisher. Com a presença da música e da cultura alcobacense. Com a experiência dos jovens. Com o envolvimento das famílias.</p><div class="card"><div class="card-image"><figure class="image"><img src="/img/insights/insights-003-tsmp-bay.jpg" alt="Parque de Transição"/></figure></div></div><p>E foi também assim com a transmissão em direto da <a href="/pt/events/2025/300004/overview">edição de 2025</a>.</p><p>Tanto quanto sabemos, uma transmissão desta dimensão era inédita numa prova nacional de triatlo. Mas quisemos acrescentar-lhe algo especial. Os três comentadores foram três triatletas olímpicos portugueses: Melanie Santos, João Silva e João Pereira.</p><p>Há aqui um simbolismo de que gosto particularmente. Um dos objetivos da primeira edição tinha sido homenagear os atletas olímpicos do nosso concelho. Quatro anos depois, Melanie Santos e João Silva estavam a comentar em direto a maior edição de sempre da prova que tinha começado, também, para os homenagear.</p><p>Mas nenhuma destas ideias teria tido o mesmo valor sem a comunidade.</p><p>O Triatlo de São Martinho do Porto nunca foi o trabalho de uma pessoa, nem sequer de um pequeno grupo. Foi construído por muitas dezenas de pessoas e instituições.</p><p>Escolas, escuteiros, associações, bombeiros, forças de segurança, empresas, músicos, técnicos, voluntários e muitos outros que fizeram parte da organização. Ao longo das quatro edições tivemos mais de uma centena de voluntários e quase duas dezenas de entidades locais envolvidas.</p><p>E havia algo muito visível na cara de quem participava na organização. Orgulho.</p><p>A <a href="/pt/events/2024/300003/overview">partir de 2024</a> decidimos também remunerar as entidades que asseguravam voluntariado. Não o fizemos apenas como solução operacional. Existia uma intenção clara de devolver valor à comunidade que ajudava a criar esse mesmo valor e de reforçar o sentimento de pertença ao evento.</p><p>Esse envolvimento acabou por ser uma das maiores conquistas do projeto.</p><p>O impacto também chegou à modalidade. Quando começámos, Alcobaça tinha excelentes triatletas, incluindo atletas olímpicos, mas não existia uma estrutura local dedicada ao triatlo. O TSMP ajudou a aumentar o número de praticantes adultos e esteve diretamente na origem da criação da Escola de Triatlo do CNAL, que passou a desenvolver atividade durante todo o ano.</p><p>Em 2023 quisemos perceber se aquilo que sentíamos tinha correspondência objetiva. Desafiámos o Instituto Politécnico de Leiria a realizar uma avaliação académica independente dos impactos económico, social e desportivo do evento.</p><p>Os <a href="https://revistas.um.es/cpd/article/view/596661/362981" target="_blank" rel="noopener">resultados</a> confirmaram aquilo que víamos no terreno. Elevados níveis de satisfação dos atletas, uma forte ligação da população ao evento e um impacto económico no concelho estimado em cerca de um milhão de euros.</p><p>O evento continuou a crescer.</p><p>Em 2025 atingimos 1.768 inscrições, das quais 503 na Prova Aberta, números sem precedentes numa prova nacional de triatlo. Tivemos atletas provenientes de 15 dos 18 distritos de Portugal e oriundos de seis nacionalidades.</p><p>Mas os números, por si só, não explicam aquilo que aconteceu naquele fim de semana.</p><p>Talvez quem melhor o tenha sintetizado tenha sido alguém que chegou a São Martinho do Porto vindo de fora.</p><p>Na edição de 2025 esteve connosco Alan Ryan, Vice-Presidente da Europe Triathlon, com uma enorme experiência em provas internacionais, de Jogos Olímpicos a Taças de Mundo, passando por Campeonatos do Mundo e da Europa.</p><p>Quando Melanie Santos lhe perguntou se São Martinho do Porto tinha condições para receber uma prova internacional, a resposta foi inequívoca. Disse que o local era um dos melhores que alguma vez tinha visto, que a prova estava a um nível profissional e, depois de recordar a sua experiência nos maiores eventos mundiais da modalidade, resumiu a sua avaliação numa expressão simples:</p><blockquote><strong>“This is right up there.”</strong></blockquote><p>Estávamos ao nível dessas provas.</p><p>Pouco tempo depois, a candidatura de São Martinho do Porto para receber uma Taça da Europa de Triatlo foi aprovada.</p><div class="card"><div class="card-image"><figure class="image"><img src="/img/insights/insights-003-tsmp-opening-cerimony.jpg" alt="Cerimónia de Abertura"/></figure></div></div><p>Nunca encarámos esse reconhecimento como o objetivo final. Foi, sobretudo, a consequência natural de um percurso de quatro anos e da qualidade que muitas pessoas ajudaram a construir.</p><p>Talvez seja também por isso que gosto particularmente do filme produzido sobre a edição de 2025, “<em><a href="https://www.youtube.com/watch?v=31C8KIR9vb0" target="_blank" rel="noopener">The Bay of Dreams</a></em>”. Não é apenas um filme sobre uma competição. É um filme sobre atletas, território, emoção, público e pessoas. E é significativo que tenha começado a receber distinções em festivais de vários países. De alguma forma, São Martinho do Porto continuou a viajar mesmo depois de terminada a prova.</p><p>Quando olho para as quatro edições, o sentimento dominante é uma mistura de orgulho e gratidão.</p><p>Orgulho pelo nível que conseguimos alcançar, muito para além daquilo que imaginávamos quando começámos.</p><p>Gratidão a todas as pessoas que acreditaram no projeto, que trabalharam, que arriscaram, que resolveram problemas e que deram um pouco de si para que tudo acontecesse.</p><p>Hermínio Rodrigues e Sérgio Dias ajudaram a definir o rumo inicial, mas o sucesso do Triatlo de São Martinho do Porto pertence a um conjunto muito alargado de pessoas.</p><p>Nenhuma organização desta dimensão se constrói individualmente.</p><p>Se tivesse de deixar apenas uma ideia sobre estas quatro edições, seria esta:</p><p><strong>Acredito convictamente que o Triatlo de São Martinho do Porto mudou a forma de organizar triatlo de curta distância em Portugal.</strong></p><p>E talvez isso tenha acontecido porque nunca olhámos para o evento apenas como uma competição.</p><p><strong>Um evento desportivo deve ser uma grande festa para os atletas e para os espectadores.</strong></p><p>The Bay of Dreams. Triatlo de São Martinho do Porto 2025: <a href="https://www.youtube.com/watch?v=31C8KIR9vb0&amp;t=1s" target="_blank" rel="noopener">Ver o filme no YouTube</a></p><div class="card"><div class="card-image"><figure class="image"><img src="/img/insights/insights-003-tsmp-ricardo-santos.jpg" alt="Ricardo Santos"/></figure></div></div><p>Ricardo Santos</p><p>Responsável pela organização do Triatlo de São Martinho do Porto, 2022-2025</p>',
    'Triatlo de São Martinho do Porto: Muito mais do que uma prova',
    'Ricardo Santos conta a história das quatro edições do Triatlo de São Martinho do Porto, do telefonema que esteve na origem à prova de nível mundial.',
    0,
    NOW(),
    NULL
  );

-- EN content for Article 3
INSERT INTO
  endurancetrio_hub.article_content (id, article_id, locale, title, subtitle, intro_text, full_text, meta_title, meta_description, version, created_at, updated_at)
VALUES
  (
    6,
    3,
    'en',
    'São Martinho do Porto Triathlon: Much more than a race',
    NULL,
    '<p>The story of the São Martinho do Porto Triathlon began, in a way, with a phone call.</p>',
    '<p>At the end of 2021, I had just challenged a dozen friends from Alcobaça to do the IRONMAN 70.3 Cascais the following year. After several years competing for a club from Sintra, I wanted to create a triathlon community in Alcobaça. I spoke with the Board of the Alcobaça Swimming Club (CNAL) and that is how the Triathlon Section of CNAL was born.</p><p>Certain day, one of those friends called me asking if I knew why a Portuguese Triathlon Federation vehicle was parked in front of the Alcobaça Town Hall. I had no idea.</p><p>I called João Raimundo, who knew Sérgio Dias personally, then President of the Federation. A few minutes later we learned that Hugo Nalha, Vice-President of the Federation, had met with João Santos, the Councillor for Sport, to assess the possibility of hosting a triathlon race in São Martinho do Porto. The answer at that time was negative, the reason being that an event of that nature would only make sense if there was a triathlon club in the municipality.</p><p>The irony was obvious.</p><p><strong>Everything that was needed was there, except the knowledge that everything was there.</strong></p><p>I knew Hermínio Rodrigues, Mayor of Alcobaça, professionally, and asked him for a meeting to present the newly founded Triathlon Section of CNAL. From there, everything happened quickly.</p><p>When the Town Hall, the Portuguese Triathlon Federation, the Parish Council of São Martinho do Porto and CNAL sat at the same table, it was very easy to realize that there was a powerful confluence of desires.</p><p>What the event would eventually become was profoundly shaped by two statements from that meeting.</p><p>Hermínio Rodrigues challenged us:</p><blockquote><strong>"Organise an event that makes the people of Alcobaça proud."</strong></blockquote><p>Sérgio Dias added:</p><blockquote><strong>"CNAL takes care of the party, the FTP takes care of the competition."</strong></blockquote><p>I believe that the DNA of the São Martinho do Porto Triathlon was born right there.</p><p>We defined five objectives. Promote São Martinho do Porto. Promote sport and triathlon in the municipality and the region. Honour the Olympic triathletes of Alcobaça. Create a high-quality event that would positively impress athletes and spectators. Bring to a sprint-distance race some of the quality and glamour we find in major international long-distance events.</p><p>Today, looking back at the four editions, it is especially those last two objectives that best represent what we did.</p><p>I have participated in IRONMAN Barcelona and IRONMAN Cascais. In these races, an athlete can pay close to a thousand euros for an entry and thousands of people take part. That financial scale allows the organization to offer an extraordinary experience.</p><p>At the São Martinho do Porto Triathlon, the entry fee was around 20 euros.</p><p><strong>Our challenge was to look at what is best done in the world, but keep our feet firmly planted in our reality.</strong></p><p>That forced us to be creative.</p><p>Perhaps the best example of that forward creative thinking is the transition area on the beach.</p><p>In the <a href="/en/events/2022/300001/overview">first edition</a>, in 2022, the transition area was set in Rua Eng. Francisco Cavaleiro. With 714 entries we immediately realised that space would not allow us to keep up with the predicted growth indicators.</p><p>On 4 December 2022, at around 6 PM, myself, Sérgio Dias, Nuno Vieira, President of the Parish Council of São Martinho do Porto, and João Raimundo were on the beach. We had chosen that time because the tide was similar to the <a href="/en/events/2023/300002/overview">race day and time in 2023</a> and we needed to analyse several technical aspects.</p><p>The problem of the transition area came back into conversation.</p><p>Between jokes and some desperation, solutions emerged like "we tear down a building", "we push the building aside" or "we pave the beach".</p><p>Until the joke stopped seeming completely absurd.</p><p>I said: paving the beach, no, obviously, but perhaps we could find a material rigid enough to allow athletes to run over the sandy beach.</p><p>We started exploring the idea. We found a local company that produced wooden boards for construction and that had material with aesthetic defects that could be purchased at a price compatible with our resources.</p><p>And the transition area on the beach was born.</p><p>What started almost as a joke became one of the most striking images of the event and completely changed the race organisation, reduced the impact on the town''s traffic and created an extraordinary competition zone for athletes and spectators. And perhaps the best transition area in the world!</p><p>From the very first edition we understood that the São Martinho do Porto Triathlon would not be a race like any other. Basically everything we tried to do started with a very simple question:</p><p><strong>How can we make it better for those who participate and those who watch?</strong></p><p>It was the same with the grandstands. With the meals offered to athletes and companions. With the merchandise. With the giant screens. With the sound system. With the opening ceremonies. With the event communication. With the finisher awards. With the presence of Alcobaça''s music and culture. With the experience of the young people. With family involvement.</p><div class="card"><div class="card-image"><figure class="image"><img src="/img/insights/insights-003-tsmp-bay.jpg" alt="Transition Area"/></figure></div></div><p>And it was also the same with the live broadcast of the <a href="/en/events/2025/300004/overview">2025 edition</a>.</p><p>As far as we know, a broadcast of this scale was unprecedented in a national triathlon event. But we wanted to add something special. It was achieved when three Portuguese Olympic triathletes: Melanie Santos, João Silva and João Pereira, got together as the event commentators.</p><p>There is a symbolism here that I particularly enjoy. One of the objectives of the first edition had been to honour the Olympic athletes from our municipality. Four years later, Melanie Santos and João Silva were commentating live on the biggest ever edition of the race that had also started, to honour them.</p><p>But none of these ideas and achievements would have had the same value without the community.</p><p>The São Martinho do Porto Triathlon was never the work of a person, not even a small group. It was built by many dozens of people and institutions.</p><p>Schools, scouts, associations, firefighters, security forces, companies, musicians, technicians, volunteers and many others who were part of the organisation. Over the four editions we had more than a hundred volunteers and nearly twenty local entities involved.</p><p>And there was something very visible in the faces of those involved in the organisation. Pride.</p><p><a href="/en/events/2024/300003/overview">Starting in 2024</a> we also decided to remunerate the entities that provided volunteers. We did it not just as an operational solution. There was a clear purpose to give back value to the community that helped create it and to strengthen the sense of belonging.</p><p>That large involvement ended up being one of the greatest achievements of the project.</p><p>The impact also reached the sport itself. When we started, Alcobaça had excellent triathletes, including Olympic athletes, but there was no local structure dedicated to triathlon. The São Martinho do Porto Triathlon helped increase the number of adult athletes and was directly responsible for the creation of the CNAL Triathlon School, which continues to operate to this day.</p><p>In 2023 we wanted to understand whether what we felt had an objective correspondence and measure. We challenged the Polytechnic Institute of Leiria to carry out an independent academic assessment of the event''s economic, social and sporting impacts.</p><p>The <a href="https://revistas.um.es/cpd/article/view/596661/362981" target="_blank" rel="noopener">results</a> confirmed what we saw on the ground. High levels of athlete satisfaction, a strong connection between the population and the event, and an estimated economic impact on the municipality of around one million euros.</p><p>The event continued to grow.</p><p>In 2025 we reached 1,768 entries, of which 503 in the Open Race, unprecedented numbers for a national triathlon event. We had athletes from 15 of Portugal''s 18 districts and from six nationalities.</p><p>But the numbers alone do not explain what happened on that weekend.</p><p>Perhaps the person who best captured it was someone who came to São Martinho do Porto from abroad.</p><p>In the 2025 edition, Alan Ryan, Vice-President of Europe Triathlon, attended the event. With him came an enormous experience in international events, from Olympic Games to World Cups, through World and European Championships, gathered from many years in the triathlon scene.</p><p>When Melanie Santos asked him whether São Martinho do Porto had the conditions to host an international event, the answer was unequivocal. He said the location was one of the best he had ever seen, that the event was at a professional level and, after recalling his experience at the world''s biggest events in the sport, he summed up his assessment in a simple expression:</p><blockquote><strong>"This is right up there."</strong></blockquote><p>We were at the level of those races.</p><p>Not long after, the candidacy of São Martinho do Porto to host a European Triathlon Cup was approved.</p><div class="card"><div class="card-image"><figure class="image"><img src="/img/insights/insights-003-tsmp-opening-cerimony.jpg" alt="Opening Ceremony"/></figure></div></div><p>That recognition was never taken as the ultimate goal. It was, above all, the natural sequence of a four-year journey and the quality confirmation of the event that many people helped to build.</p><p>Perhaps that is also why I particularly like the film produced about the 2025 edition, "<strong><a href="https://www.youtube.com/watch?v=31C8KIR9vb0" target="_blank" rel="noopener">The Bay of Dreams</a></strong>". It is not just a film about a competition. It is a film about athletes, territory, emotion, spectators and people. And it is significant that it is an award winning film in international film festivals around the world. In some way, São Martinho do Porto continued to travel even after the race ended.</p><p>When I look back at the four editions, the dominant feeling is a mixture of pride and gratitude.</p><p>Pride for the high level we managed to achieve, far beyond what we imagined when we started.</p><p>Gratitude to all the people who believed in the project, who worked, who took risks, who solved problems and who gave a little of themselves to make it all happen.</p><p>Hermínio Rodrigues and Sérgio Dias helped set the initial course, but the success of the São Martinho do Porto Triathlon belongs to a very wide group of people.</p><p>No organisation of this scale is built individually.</p><p>If I had to summarize in a sentence all these four editions, it would be this:</p><p><strong>I firmly believe that the São Martinho do Porto Triathlon changed the way short-distance triathlon is organised in Portugal.</strong></p><p>And perhaps that happened because we never looked at the event as just a competition.</p><p><strong>A sporting event should be a great celebration for athletes and spectators.</strong></p><p>The Bay of Dreams. São Martinho do Porto Triathlon 2025: <a href="https://www.youtube.com/watch?v=31C8KIR9vb0" target="_blank" rel="noopener">Watch the film on YouTube</a>.</p><div class="card"><div class="card-image"><figure class="image"><img src="/img/insights/insights-003-tsmp-ricardo-santos.jpg" alt="Ricardo Santos"/></figure></div></div><p>Ricardo Santos</p><p>Head of the organisation of the São Martinho do Porto Triathlon, 2022–2025</p>',
    'São Martinho do Porto Triathlon: Much more than a race',
    'Ricardo Santos tells the story of the four editions of the São Martinho do Porto Triathlon, from the phone call that started it all to a world-class race.',
    0,
    NOW(),
    NULL
  );

-- Link Article 3 to the São Martinho do Porto Triathlon events (only when present in the database)
INSERT INTO
  endurancetrio_hub.article_event (article_id, event_id)
SELECT
  3, id
FROM
  endurancetrio_hub.event
WHERE
  id IN (300001, 300002, 300003, 300004);

SELECT setval('seq_author_id', 5, FALSE);
SELECT setval('seq_article_id', 4, FALSE);
SELECT setval('seq_article_content_id', 7, FALSE);
